<?php if (!empty($legacyNotice)): ?><p class="tm-note" role="status"><?= e($legacyNotice) ?></p><?php endif; ?>
<form class="tm-filters tm-card" method="get" action="/tickets" data-ticket-form>
  <label>Workflow<select name="status"><?php foreach (['active'=>'All active (excluding closed)','all'=>'All tickets']+TICKET_STATUSES as $value=>$label): ?><option value="<?= e($value) ?>"<?= $filters['status']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
  <label>Intake source<select name="source"><?php foreach ([''=>'All sources','clog'=>'CLOG','email'=>'Email','portal'=>'Portal'] as $value=>$label): ?><option value="<?= e($value) ?>"<?= $filters['source']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
  <label>Assigned agent<select name="agent"><option value="">All agents</option><option value="unassigned"<?= $filters['agent']==='unassigned'?' selected':'' ?>>Unassigned</option><?php foreach ($agents as $agent): ?><option value="<?= e($agent['id']) ?>"<?= $filters['agent']===$agent['id']?' selected':'' ?>><?= e($agent['username'].(!$agent['is_active']?' (inactive)':'')) ?></option><?php endforeach; ?></select></label>
  <label>Queue / team<select name="bucket"><option value="">All teams</option><?php foreach ($buckets as $bucket): ?><option value="<?= e($bucket['id']) ?>"<?= $filters['bucket']===$bucket['id']?' selected':'' ?>><?= e($bucket['name'].(!$bucket['is_active']?' (inactive)':'')) ?></option><?php endforeach; ?></select></label>
  <label>Sort by<select name="sort"><?php foreach (['updated_desc'=>'Recently updated','created_desc'=>'Newest first','created_asc'=>'Oldest first'] as $value=>$label): ?><option value="<?= e($value) ?>"<?= $filters['sort']===$value?' selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select></label>
  <label>Per page<select name="per_page"><?php foreach ([20,50,100] as $size): ?><option<?= $filters['per_page']===$size?' selected':'' ?>><?= $size ?></option><?php endforeach; ?></select></label>
  <label class="tm-check"><input type="checkbox" name="clog_open" value="1"<?= $filters['clog_open']==='1'?' checked':'' ?>> Active CLOG work (source status Open)</label>
  <div class="tm-filter-actions"><button class="tm-button tm-primary" type="submit">Apply filters</button><a href="/tickets">Reset</a></div>
</form>
<section class="tm-card tm-queue">
  <div class="tm-list-heading"><h2><?= e($filters['status']==='active'?'Active tickets':($filters['status']==='all'?'All tickets':ticket_label($filters['status']))) ?></h2><span><?= number_format($total) ?> <?= $total===1?'ticket':'tickets' ?></span></div>
  <?php if (!$rows): ?><div class="tm-empty"><span aria-hidden="true">◇</span><h3>No tickets in this view</h3><p>Try a different workflow, source, agent or team.</p><a href="/tickets">View active tickets</a></div><?php else: ?>
  <div class="tm-table-wrap"><table class="tm-table"><caption class="tm-sr-only">Ticket queue. Open a ticket to view its details.</caption><thead><tr><th scope="col">Ticket / requester</th><th scope="col">Workflow</th><th scope="col">Assignment</th><th scope="col">Source / CRM</th><th scope="col">Updated</th></tr></thead><tbody>
  <?php foreach ($rows as $row): ?><tr>
    <td><a class="tm-ticket-title" href="/tickets/<?= e($row['id']) ?>"><?= e($row['applicant_name'] ?: 'Unnamed requester') ?></a><span class="tm-uuid tm-subtext"><?= e($row['id']) ?></span><span class="tm-subtext"><?= e($row['applicant_email'] ?: 'Email not provided') ?></span><span class="tm-subtext"><?= e($row['scenario_key'] ?: 'Scenario not classified') ?></span></td>
    <td><span class="tm-badge tm-<?= e($row['workflow_status']) ?>"><?= e(ticket_label($row['workflow_status'])) ?></span><span class="tm-subtext"><?= e(ticket_label($row['customer_type'])) ?></span><?php if ($row['missing_fields']): ?><span class="tm-subtext"><?= count($row['missing_fields']) ?> missing <?= count($row['missing_fields'])===1?'field':'fields' ?></span><?php endif; ?><span class="tm-subtext">Attachment lookup: <?= e(ticket_label($row['attachment_lookup_status'])) ?></span></td>
    <td><?= e($row['assigned_username'] ?: 'Unassigned') ?><span class="tm-subtext"><?= e($row['bucket_name'] ?: 'No team assigned') ?></span></td>
    <td><span class="tm-source"><?= e(strtoupper($row['source_type'])) ?></span><?php if ($row['clog_crm_id']): ?><a class="tm-subtext" href="/tickets/crm?crm_id=<?= rawurlencode($row['clog_crm_id']) ?>"><?= e($row['clog_crm_id']) ?></a><?php else: ?><span class="tm-subtext">No CRM linked</span><?php endif; ?><span class="tm-subtext">CLOG status: <?= e($row['clog_status'] ?: 'Not provided') ?></span><span class="tm-subtext">Reference: <?= e($row['source_ref'] ?: 'Not provided') ?></span></td>
    <td><?= e(ticket_date($row['updated_at'])) ?><span class="tm-subtext">Created <?= e(ticket_date($row['created_at'])) ?></span></td>
  </tr><?php endforeach; ?></tbody></table></div>
  <?php endif; ?>
  <nav class="tm-pagination" aria-label="Ticket pagination"><span><?= $total ? (($filters['page']-1)*$filters['per_page']+1).'–'.min($total,$filters['page']*$filters['per_page']).' of '.number_format($total) : '0 tickets' ?></span><div><?php if ($filters['page']>1): ?><a class="tm-button" rel="prev" href="<?= e(ticket_link(['page'=>$filters['page']-1],$filters)) ?>">← Previous</a><?php endif; ?><span>Page <?= $filters['page'] ?> of <?= $pages ?></span><?php if ($filters['page']<$pages): ?><a class="tm-button" rel="next" href="<?= e(ticket_link(['page'=>$filters['page']+1],$filters)) ?>">Next →</a><?php endif; ?></div></nav>
</section>
